-- FASE D · Bloque 4 · Profetas menores 3: Sofonías, Hageo, Zacarías y Malaquías
update public.biblical_books set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('coverage_status','context_ready'),updated_at=now() where code in ('ZEP','HAG','ZEC','MAL');
with source as (select id from public.biblical_sources where slug='vida-contexto-editorial'),data(slug,book_code,scope_kind,chapter_start,chapter_end,title,summary,historical_context,jewish_context,literary_context,authorial_intent,theological_reflection,interpretive_cautions,key_terms,people_groups,places) as (values
('sofonias-perfil','ZEP','book',1,3,'Sofonías: día de YHWH, purificación y comunidad humilde','Sofonías anuncia un día de evaluación contra Judá y las naciones, denuncia complacencia, idolatría y violencia y termina con una comunidad humilde, retorno y canto de restauración.','El encabezado sitúa al profeta en tiempos de Josías, antes o durante reformas del siglo VII a. C., cuando prácticas asirias y cultos diversos influían en Judá.','El día de YHWH revierte expectativas: no será automáticamente victoria para Judá, pues comienza evaluando Jerusalén. El remanente humilde busca justicia y refugio.','Oráculos de juicio se expanden desde Judá hacia naciones y vuelven a Jerusalén; un giro final reúne pueblos y transforma vergüenza en canto.','Advertir que pertenencia religiosa no protege la complacencia y mostrar que la restauración se reconoce por humildad, justicia y ausencia de engaño.','Buscar a Dios incluye buscar justicia y humildad. El propósito de la corrección no es mantener vergüenza, sino formar una comunidad capaz de recibir y dar alegría.','El día de YHWH no debe usarse para predecir una fecha ni celebrar desastres. El lenguaje universal es profético y no una invitación a miedo constante.',ARRAY['Sofonías','día de YHWH','remanente','humildad','justicia','canto']::text[],ARRAY['Judá','naciones','pobres','gobernantes']::text[],ARRAY['Jerusalén','Judá','Filistea','Moab','Asiria']::text[]),
('sofonias-1-2-dia-naciones','ZEP','section',1,2,'Día de YHWH y oráculos contra naciones','El profeta anuncia evaluación sobre idolatría, funcionarios, comerciantes y personas indiferentes, llama a buscar justicia y dirige oráculos hacia pueblos vecinos y Asiria.','La influencia asiria alcanzaba vestimenta, religión y política. Mercados y barrios de Jerusalén reflejaban una economía conectada con poderes regionales.','La frase sobre quienes creen que Dios no hará bien ni mal describe indiferencia práctica, no una duda intelectual honesta.','Una descripción intensa del día conduce a un llamado urgente y luego a un recorrido geográfico que termina en Nínive.','Mostrar que la indiferencia ante injusticia también es una postura moral y que ningún centro imperial permanece fuera de evaluación.','La humildad no es desprecio propio, sino disposición a escuchar y cambiar antes de que la complacencia endurezca decisiones.','Las imágenes de destrucción no deben representarse gráficamente ni usarse para aterrorizar. Buscar refugio no garantiza ausencia de toda dificultad física.',ARRAY['idolatría','complacencia','comerciantes','día de YHWH','justicia','Nínive']::text[],ARRAY['judíos','comerciantes','funcionarios','naciones']::text[],ARRAY['Jerusalén','Filistea','Moab','Amón','Nínive']::text[]),
('sofonias-3-restauracion','ZEP','section',3,3,'Jerusalén corregida y Dios que canta','Después de acusar a gobernantes, jueces, profetas y sacerdotes, el poema anuncia pueblos con labios purificados, un remanente sin engaño y la restauración de personas avergonzadas y dispersas.','La corrupción institucional podía sobrevivir incluso dentro de una ciudad con templo y tradición. La reunión de dispersos anticipa experiencias de exilio y retorno.','La imagen de Dios alegrándose y cantando sobre el pueblo es una de las expresiones más tiernas del libro y equilibra el lenguaje previo de juicio.','Una última acusación se transforma progresivamente en invitación a cantar; la voz cambia desde condena pública hacia presencia y restauración.','Afirmar que la renovación institucional requiere verdad y humildad, y que la meta divina no es humillación permanente sino una comunidad segura y restaurada.','La presencia de Dios puede aquietar miedo y devolver voz a quien fue avergonzado. La alegría no borra el proceso de justicia que la hizo posible.','«Dios está en medio» no significa que toda institución religiosa esté aprobada. El canto de restauración no debe usarse para exigir emociones positivas a quien aún está procesando dolor.',ARRAY['gobernantes','profetas','remanente','labios puros','canto','restauración']::text[],ARRAY['líderes','pobres','dispersos','naciones']::text[],ARRAY['Jerusalén','Sion']::text[]),
('hageo-perfil','HAG','book',1,2,'Hageo: prioridades, templo y esperanza postexílica','Hageo llama a la comunidad retornada a reconstruir el templo, interpreta su desánimo y dificultades económicas y anima a Zorobabel, Josué y el pueblo con la promesa de presencia.','El libro está fechado en 520 a. C., durante Darío I. Judá era una provincia persa pequeña y el templo seguía incompleto después del retorno.','La reconstrucción del segundo templo restauraba culto y cohesión comunitaria, aunque no recuperaba independencia política ni el esplendor recordado del templo de Salomón.','Cuatro mensajes fechados vinculan cosechas, trabajo, pureza, memoria y liderazgo. La fórmula «consideren sus caminos» organiza la exhortación.','Mostrar que una comunidad puede normalizar proyectos privados mientras una responsabilidad común permanece abandonada, y que la presencia de Dios acompaña una reconstrucción modesta.','Revisar prioridades no exige despreciar necesidades personales. Significa preguntar cómo recursos, tiempo y trabajo contribuyen también al bien compartido.','Hageo no enseña que toda dificultad económica sea castigo por no donar a un edificio religioso. La prioridad del templo pertenece a la restauración específica de Judá y no autoriza manipulación financiera.',ARRAY['Hageo','templo','Zorobabel','Josué','prioridades','presencia','reconstrucción']::text[],ARRAY['judíos retornados','sacerdotes','gobernador']::text[],ARRAY['Jerusalén','Yehud','templo']::text[]),
('hageo-1-reconstruccion','HAG','section',1,1,'Considerar los caminos y comenzar la obra','El profeta confronta la demora, relaciona trabajo sin satisfacción con prioridades desordenadas y la comunidad responde iniciando la reconstrucción bajo la promesa «yo estoy con ustedes».','La población enfrentaba cosechas limitadas, impuestos persas y recursos escasos. Las casas cubiertas contrastan con el templo en ruinas, aunque el grado de lujo es debatido.','Zorobabel representa liderazgo davídico limitado bajo Persia y Josué liderazgo sacerdotal. La respuesta colectiva es presentada como acción de Dios en sus espíritus.','Dos acusaciones enmarcan la obediencia del pueblo y una breve palabra de presencia transforma reproche en acción.','Invitar a evaluar la distancia entre valores declarados y asignación real de recursos, y mostrar que el cambio comienza con una acción comunitaria concreta.','La presencia no espera una obra perfecta. Acompaña a una comunidad que escucha, organiza y empieza con lo que tiene.','No debe aplicarse el texto para exigir que familias descuiden vivienda, comida o salud por un proyecto religioso. La comparación de casas y templo requiere contexto económico.',ARRAY['considerar','caminos','cosecha','templo','obediencia','presencia']::text[],ARRAY['retornados','Zorobabel','Josué','trabajadores']::text[],ARRAY['Jerusalén','templo']::text[]),
('hageo-2-gloria-esperanza','HAG','section',2,2,'Desánimo, pureza y el sello de Zorobabel','La comunidad compara el nuevo templo con el anterior, recibe ánimo para trabajar, escucha una enseñanza sobre pureza y termina con una promesa simbólica a Zorobabel.','Personas mayores podían recordar el templo anterior o tradiciones sobre él. La provincia continuaba bajo control persa y sin rey independiente.','La gloria futura se relaciona con presencia y reunión de recursos, no solamente con tamaño. La imagen del anillo de sello revierte el juicio sobre la línea davídica sin convertir a Zorobabel en monarca efectivo.','Tres palabras fechadas responden a desánimo, contaminación ritual y expectativas políticas.','Enseñar que comparar constantemente con un pasado ideal puede paralizar y que la fidelidad presente posee valor aun sin recuperar antiguas formas.','La obra pequeña puede ser significativa cuando está orientada por presencia, justicia y esperanza. La identidad no depende de superar a generaciones anteriores.','«La gloria postrera» no garantiza edificios más costosos ni prosperidad institucional. Sacudir naciones no ofrece una fecha ni justifica revolución violenta.',ARRAY['gloria','desánimo','pureza','Zorobabel','sello','presencia']::text[],ARRAY['retornados','sacerdotes','gobernador']::text[],ARRAY['Jerusalén','templo']::text[]),
('zacarias-perfil','ZEC','book',1,14,'Zacarías: retorno, visiones y esperanza del reino','Zacarías combina llamados al retorno, ocho visiones nocturnas, coronación simbólica y oráculos posteriores sobre un rey humilde, un pastor herido, Jerusalén y el día de YHWH.','Los primeros capítulos están fechados entre 520 y 518 a. C. bajo Persia y comparten contexto con Hageo. Los capítulos 9–14 poseen estilo y situación diferentes, y su relación compositiva es debatida.','Las visiones apoyan reconstrucción del templo y liderazgo de Josué y Zorobabel. Textos sobre el rey humilde y quien es traspasado recibieron interpretaciones judías y cristianas diversas.','Ocho visiones forman una secuencia simétrica alrededor de purificación y templo; los capítulos finales usan poesía profética y apocalíptica más difícil de fechar.','Sostener a una comunidad pequeña mediante la certeza de que Dios recuerda, purifica y actúa, sin convertir poder político o militar en centro de restauración.','La esperanza puede comenzar con volver y construir. «No con ejército ni con fuerza» orienta hacia dependencia del Espíritu y no hacia pasividad.','Los símbolos no deben leerse como códigos exactos de eventos modernos. Zacarías 9–14 debe distinguir horizonte profético, usos en el Nuevo Testamento y sistemas escatológicos posteriores.',ARRAY['Zacarías','visiones','Josué','Zorobabel','Espíritu','rey humilde','día de YHWH']::text[],ARRAY['judíos retornados','sacerdotes','persas','naciones']::text[],ARRAY['Jerusalén','Babilonia','templo','monte de los Olivos']::text[]),
('zacarias-1-6-visiones','ZEC','section',1,6,'Retorno y ocho visiones nocturnas','Zacarías llama a volver, contempla jinetes, cuernos, un medidor, la purificación de Josué, un candelabro, un rollo y carros, y realiza una coronación simbólica.','La comunidad reconstruía bajo autoridad persa y podía sentirse insignificante frente a imperios. Zorobabel y Josué representaban administración y sacerdocio.','La acusación contra Josué y su vestidura limpia expresa restauración sacerdotal. El candelabro y los olivos se relacionan con liderazgo sostenido por el Espíritu.','Las visiones forman pares y colocan la purificación del sacerdocio y la palabra a Zorobabel en el centro.','Mostrar que la reconstrucción necesita retorno, limpieza institucional y liderazgo que no dependa únicamente de fuerza humana.','Dios puede llamar «día de pequeñeces» a una etapa que otros desprecian y aun así valorar cada avance fiel.','«No con ejército» no significa rechazar toda organización o protección. Las figuras visionarias no deben convertirse en ángeles personales o códigos geopolíticos sin evidencia.',ARRAY['jinetes','Josué','Zorobabel','candelabro','olivos','Espíritu','corona']::text[],ARRAY['retornados','sacerdotes','líderes']::text[],ARRAY['Jerusalén','Babilonia','templo']::text[]),
('zacarias-7-8-ayuno-justicia','ZEC','section',7,8,'Ayunos, justicia y ciudad restaurada','Una pregunta sobre continuar ayunos de duelo recibe una respuesta que denuncia culto autocentrado y llama a justicia, misericordia y verdad antes de prometer una Jerusalén segura para ancianos y niños.','Los ayunos recordaban la caída de Jerusalén. Con el templo en reconstrucción surgía la pregunta de cómo transformar memoria de desastre en vida renovada.','La respuesta conecta la antigua caída con el rechazo a escuchar justicia hacia viuda, huérfano, extranjero y pobre. La restauración atrae a pueblos que buscan a Dios.','Dos años después de las visiones, una consulta ritual se convierte en revisión ética y luego en una serie de promesas de paz comunitaria.','Enseñar que una práctica de duelo pierde sentido si no produce misericordia y que la restauración se mide por seguridad y convivencia intergeneracional.','La memoria sana no repite dolor por costumbre; transforma hábitos y crea una ciudad donde personas vulnerables pueden vivir sin miedo.','El texto no elimina el valor del ayuno, sino el ayuno centrado en uno mismo. La promesa de tomar el manto de un judío no autoriza apropiación cultural ni superioridad étnica.',ARRAY['ayuno','justicia','misericordia','verdad','ancianos','niños','Jerusalén']::text[],ARRAY['retornados','ancianos','niños','extranjeros','pobres']::text[],ARRAY['Jerusalén','Sion']::text[]),
('zacarias-9-14-rey-dia','ZEC','section',9,14,'Rey humilde, pastores y día de YHWH','Los capítulos finales anuncian un rey humilde, confrontan pastores, describen duelo por una figura herida y presentan una transformación final de Jerusalén y las naciones.','El trasfondo exacto es debatido y puede reflejar periodos posteriores al primer Zacarías. Las referencias a Grecia y conflictos regionales señalan horizontes cambiantes.','El rey sobre un asno se relaciona con paz y fin de carros; tradiciones cristianas lo aplican a la entrada de Jesús. El duelo y el pastor fueron también releídos en el Nuevo Testamento.','Poemas y oráculos sin fechas reemplazan las visiones iniciales. Imágenes apocalípticas combinan juicio, purificación, agua viva y peregrinación de naciones.','Esperar un liderazgo humilde y una restauración donde guerra, idolatría y explotación pierdan dominio.','La esperanza mesiánica debe producir humildad y paz, no culto al poder. El duelo puede convertirse en purificación y responsabilidad.','El lenguaje del día de YHWH no permite fijar una guerra moderna como cumplimiento seguro. Las diferencias entre interpretaciones judías y cristianas deben mostrarse sin presentar una como dato lingüístico indiscutible.',ARRAY['rey humilde','asno','pastor','traspasado','agua viva','día de YHWH']::text[],ARRAY['Judá','Jerusalén','naciones','pastores']::text[],ARRAY['Jerusalén','monte de los Olivos']::text[]),
('malaquias-perfil','MAL','book',1,4,'Malaquías: culto, justicia del pacto y mensajero futuro','Malaquías presenta disputas entre Dios y una comunidad postexílica sobre amor, sacerdocio, matrimonio, justicia, contribuciones y la aparente prosperidad del malvado, y termina esperando un mensajero antes del día de YHWH.','El templo estaba funcionando bajo Persia, pero la comunidad enfrentaba desánimo, economía limitada y liderazgo sacerdotal deficiente. El nombre Malaquías puede significar «mi mensajero» y su identificación personal es debatida.','El libro cierra el Libro de los Doce y, en el orden cristiano, el Antiguo Testamento. La expectativa de Elías se relaciona con reconciliación generacional y recibió desarrollos judíos y cristianos.','Seis disputas siguen el patrón de afirmación, objeción de la comunidad y respuesta divina. El cierre conecta Torá de Moisés y expectativa profética.','Confrontar una religión cansada que ofrece lo sobrante, protege injusticia relacional y concluye que servir no vale la pena.','La fidelidad no consiste en fingir entusiasmo, sino en recuperar honra, justicia y responsabilidad dentro de prácticas concretas.','Los textos sobre matrimonio no deben usarse para obligar a permanecer en abuso. La referencia al diezmo pertenece al sistema del templo y no autoriza prometer enriquecimiento ni amenazar a quien no entrega dinero.',ARRAY['Malaquías','sacerdotes','pacto','mensajero','diezmo','Elías','día de YHWH']::text[],ARRAY['judíos retornados','sacerdotes','familias']::text[],ARRAY['Jerusalén','templo']::text[]),
('malaquias-1-2-culto-pacto','MAL','section',1,2,'Ofrendas deficientes, sacerdocio y fidelidad relacional','La comunidad pregunta cómo ha sido amada, los sacerdotes ofrecen animales deficientes y la acusación se amplía hacia enseñanza parcial y traición dentro de relaciones de pacto.','El templo dependía de ofrendas dentro de una economía frágil, pero los animales ofrecidos también expresaban la prioridad dada al culto. Los sacerdotes poseían responsabilidad educativa y judicial.','El pacto con Leví idealiza una enseñanza verdadera que aparta del mal. La unidad y fidelidad matrimonial se relacionan con justicia comunitaria.','Una disputa sobre amor abre hacia culto, enseñanza y relaciones, mostrando que la falta de honra atraviesa varias áreas.','Mostrar que Dios no necesita regalos defectuosos para su autoestima, sino una comunidad cuya adoración refleje integridad, enseñanza justa y trato fiel.','Dar lo mejor no significa perfeccionismo ni lujo, sino coherencia. Quien enseña posee responsabilidad de no favorecer a personas por interés.','Las traducciones de Malaquías 2:16 son difíciles y no deben resumirse simplemente como «Dios odia el divorcio» para atrapar a personas en peligro. El texto condena traición y violencia en el pacto.',ARRAY['amor','ofrendas','sacerdotes','Leví','enseñanza','pacto matrimonial']::text[],ARRAY['sacerdotes','familias','comunidad retornada']::text[],ARRAY['Jerusalén','templo']::text[]),
('malaquias-3-4-mensajero','MAL','section',3,4,'Mensajero, justicia, contribuciones y retorno de Elías','Un mensajero prepara la llegada divina, el juicio se dirige contra explotación y fraude, la comunidad es llamada a volver y un libro de memoria distingue a quienes temen a Dios antes de la promesa de Elías.','Las contribuciones sostenían levitas, templo y distribución. Retenerlas afectaba un sistema comunitario, pero la pobreza postexílica también hacía compleja la economía.','El mensajero fue interpretado de varias maneras; la expectativa de Elías forma parte de la tradición de Pascua y de esperanzas mesiánicas. El «sol de justicia» es imagen de sanidad y vindicación.','Dos disputas sobre justicia y utilidad de servir conducen a memoria, día futuro y una conclusión que une Moisés y Elías.','Enseñar que esperar justicia futura no permite ignorar salarios, extranjeros, viudas y huérfanos, y que la renovación busca reconciliar generaciones.','Volver a Dios incluye revisar economía y relaciones, pero la generosidad no es transacción para obligar a recibir riqueza.','«Abran las ventanas de los cielos» no es contrato de prosperidad individual ni autoriza presión financiera. La maldición final no debe usarse para amenazar relaciones familiares; la meta expresada es reconciliación.',ARRAY['mensajero','justicia','salarios','diezmo','libro de memoria','Elías','reconciliación']::text[],ARRAY['trabajadores','extranjeros','viudas','huérfanos','familias']::text[],ARRAY['Jerusalén','templo']::text[])
)
insert into public.biblical_context_units(slug,book_code,source_id,scope_kind,chapter_start,verse_start,chapter_end,verse_end,title,summary,historical_context,jewish_context,literary_context,authorial_intent,theological_reflection,interpretive_cautions,key_terms,people_groups,places,source_locator,provider_version,content_hash,review_status,enabled,metadata)
select data.slug,data.book_code,source.id,data.scope_kind,data.chapter_start,NULL,data.chapter_end,NULL,data.title,data.summary,data.historical_context,data.jewish_context,data.literary_context,data.authorial_intent,data.theological_reflection,data.interpretive_cautions,data.key_terms,data.people_groups,data.places,'vida://corpus/contexto/profetas-menores/v1#'||data.slug,'profetas-menores-v1-2026-08-02',encode(extensions.digest(concat_ws('|',data.slug,data.title,data.summary,data.historical_context,data.jewish_context,data.literary_context,data.authorial_intent,data.theological_reflection,data.interpretive_cautions),'sha256'),'hex'),'approved',true,jsonb_build_object('coverage_batch','minor-prophets','generated_by_ai',false,'review_level','editorial')
from data cross join source
on conflict(slug) do update set book_code=excluded.book_code,source_id=excluded.source_id,scope_kind=excluded.scope_kind,chapter_start=excluded.chapter_start,chapter_end=excluded.chapter_end,title=excluded.title,summary=excluded.summary,historical_context=excluded.historical_context,jewish_context=excluded.jewish_context,literary_context=excluded.literary_context,authorial_intent=excluded.authorial_intent,theological_reflection=excluded.theological_reflection,interpretive_cautions=excluded.interpretive_cautions,key_terms=excluded.key_terms,people_groups=excluded.people_groups,places=excluded.places,source_locator=excluded.source_locator,provider_version=excluded.provider_version,content_hash=excluded.content_hash,review_status='approved',enabled=true,metadata=excluded.metadata,updated_at=now();